#!/usr/bin/env python3
"""Pack imagegen enemy drawings; keep authored phases, foot pivots and clean guards."""
from pathlib import Path
from PIL import Image,ImageDraw
import hashlib,json,statistics,math
from segment_enemy_variants_v2 import isolate_poses
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'assets/enemies/variants-v2';CELL=128;PIVOT=(64,104);GUARD=10;STATES=['idle','prepare','attack','hurt']
TYPES={
 'tambor_escudo':('Tambor-Escudo',94,'hush','wood/copper/purple',True),
 'flautim_atirador':('Flautim Atirador',96,'whisper','olive/brass/purple',False),
 'coro_curador':('Coro de Reparo',82,'espelho','patinated green/bronze/lilac',False),
 'maestro_invocador':('Maestro Oco',104,'abafador','lavender/graphite/brass',False),
 'muralha_estatica':('Muralha de Estática',100,'abafador','rust/iron/purple cable',True),
 'antena_feedback':('Antena de Feedback',108,'compasso','rust/bronze/desaturated teal',False)}
(OUT/'atlas').mkdir(exist_ok=True);(OUT/'preview').mkdir(exist_ok=True)
manifest={'version':2,'cell':CELL,'columns':8,'states':STATES,'frames':8,'pivot':list(PIVOT),'filter':'nearest','guardPixels':GUARD,'origin':'10 original sheets generated by built-in image_gen, canonical T&H style/identity references; no external resources','sourcePolicy':'Originals retained. Global connected-component ownership BEFORE crop, all alpha>64 physical pixels preserved exactly once; bounded original antialias edges, no source-grid clipping. Nearest packing uses a constant nominal foot pivot/scale per facing, preserving authored displacement. No new/inbetween poses. Left shield facing mirrors the authored right view.','enemies':{}}
for typ,(name,size,base,palette,shield)in TYPES.items():
 dirs=['down','right','up']if shield else['down'];faces=[]
 for direction in dirs:
  src=OUT/'source'/f'{typ}_{direction}.png';raw=Image.open(src).convert('RGBA');w,h=raw.size;tiles,segmentation=isolate_poses(raw);bounds=[];tops=[];foot_x=[];foot_y=[]
  for row in range(4):
   for col in range(8):
    tile=tiles[row*8+col];a=tile.getchannel('A');b=a.getbbox();assert b,(typ,direction,row,col);bounds.append(b)
    if row==0:
     solid=a.point(lambda a:255 if a>64 else 0);sb=solid.getbbox();foot_y.append(sb[3]);tops.append(sb[1]);p=solid.load();xx=[x for y in range(max(0,sb[3]-6),sb[3])for x in range(tile.width)if p[x,y]];foot_x.append(statistics.mean(xx))
  px=statistics.median(foot_x);py=statistics.median(foot_y);scale=90/(py-statistics.median(tops))
  faces.append({'direction':direction,'source':src,'raw':raw,'tiles':tiles,'bounds':bounds,'foot':[px,py],'scale':scale,'segmentation':segmentation})
 # One correction factor for all views preserves the enemy's anatomy/height.
 correction=1.
 for face in faces:
  px,py=face['foot'];s=face['scale'];boxes=face['bounds'];ext=[max((px-b[0])*s for b in boxes),max((b[2]-px)*s for b in boxes),max((py-b[1])*s for b in boxes),max((b[3]-py)*s for b in boxes)]
  for available,needed in zip([PIVOT[0]-GUARD,CELL-GUARD-PIVOT[0],PIVOT[1]-GUARD,CELL-GUARD-PIVOT[1]],ext):
   if needed>0:correction=min(correction,available/needed)
 atlas=Image.new('RGBA',(CELL*8,CELL*4*len(faces)));entries=[];facing_map={};overall_top=CELL
 for fi,face in enumerate(faces):
  px,py=face['foot'];scale=face['scale']*correction;rows=[];facing_map[face['direction']]={'row':fi*4,'flipX':False}
  for row,state in enumerate(STATES):
   frames=[]
   for col in range(8):
    tile=face['tiles'][row*8+col];tw=max(1,round(tile.width*scale));th=max(1,round(tile.height*scale));piece=tile.resize((tw,th),Image.Resampling.NEAREST);dest=Image.new('RGBA',(CELL,CELL));x=round(PIVOT[0]-px*scale);y=round(PIVOT[1]-py*scale);dest.alpha_composite(piece,(x,y));a=dest.getchannel('A');b=a.getbbox();assert b
    assert b[0]>=GUARD-1 and b[1]>=GUARD-1 and b[2]<=CELL-GUARD+1 and b[3]<=CELL-GUARD+1,(typ,face['direction'],state,col,b)
    top=a.point(lambda a:255 if a>24 else 0).getbbox()[1];overall_top=min(overall_top,top)
    atlas.alpha_composite(dest,(col*CELL,(fi*4+row)*CELL));values=list(a.getdata());frames.append({'frame':col,'bounds':list(b),'opaqueTop':top,'alphaMass':round(sum(values)/255,2),'visiblePixels':sum(a>32 for a in values),'sha256':hashlib.sha256(dest.tobytes()).hexdigest()})
   assert len(set(f['sha256']for f in frames))==8,(typ,face['direction'],state,'duplicate frames')
   rows.append({'state':state,'row':fi*4+row,'frames':frames})
  entries.append({'direction':face['direction'],'source':str(face['source'].relative_to(OUT)),'sourceSha256':hashlib.sha256(face['source'].read_bytes()).hexdigest(),'segmentation':face['segmentation'],'sourceFootPivot':[round(px,3),round(py,3)],'uniformScale':round(scale,6),'rows':rows})
 if shield:facing_map['left']={'row':4,'flipX':True}
 elif typ=='flautim_atirador':facing_map={'right':{'row':0,'flipX':False},'left':{'row':0,'flipX':True},'down':{'row':0,'flipX':False},'up':{'row':0,'flipX':False}}
 else:facing_map={d:{'row':0,'flipX':False}for d in['down','right','up','left']}
 path=OUT/'atlas'/f'{typ}.png';atlas.save(path,optimize=True)
 entry={'name':name,'atlas':str(path.relative_to(OUT)),'atlasSize':list(atlas.size),'atlasSha256':hashlib.sha256(path.read_bytes()).hexdigest(),'drawSize':size,'legacyBase':base,'palette':palette,'shield':shield,'facings':facing_map,'headHeight':round((PIVOT[1]-overall_top)*size/CELL,3),'openPose':{'state':'hurt','frame':3}if shield else None,'playback':{'idleFrameMs':140,'prepare':'original wind/max progression','attackMs':300,'hurtFrameMs':65,'open':'original f2aberto/f2tonto flags; stable exposed torso pose'},'sources':entries}
 manifest['enemies'][typ]=entry
 # Preview faces remain separate, readable at native128px on contrasting gray.
 bg=Image.new('RGB',atlas.size,'#655b59');bg.paste(atlas,(0,0),atlas);d=ImageDraw.Draw(bg)
 for fi,face in enumerate(faces):
  for row,state in enumerate(STATES):d.text((4,(fi*4+row)*CELL+3),face['direction']+' '+state,fill='#f4deb4')
 bg.save(OUT/'preview'/f'{typ}.png')
 print(typ,atlas.size,'bodyScale',round(correction,3),'head',entry['headHeight'])
(OUT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
board=Image.new('RGB',(768,2*300),'#25212b');d=ImageDraw.Draw(board)
for i,(typ,e)in enumerate(manifest['enemies'].items()):
 im=Image.open(OUT/e['atlas']);x=i%3*256;y=i//3*300;d.text((x+4,y+4),typ,fill='#f3d6aa')
 for k,state in enumerate(STATES):
  tile=im.crop((3*CELL,k*CELL,4*CELL,(k+1)*CELL));board.paste(tile,(x+(k%2)*128,y+25+(k//2)*128),tile)
board.save(OUT/'contact-sheet.png');print(json.dumps({'types':6,'authoredFrames':sum(32*len(e['sources'])for e in manifest['enemies'].values()),'manifest':'assets/enemies/variants-v2/manifest.json'}))
